class StandartIndirim:
    def indirimli(self, tutar):
        return tutar * 90 // 100

class PremiumIndirim:
    def indirimli(self, tutar):
        return tutar * 80 // 100

class FiyatHesaplayici:
    def __init__(self, strategy):
        self.strategy = strategy

    def hesapla(self, tutar):
        return self.strategy.indirimli(tutar)

print(FiyatHesaplayici(StandartIndirim()).hesapla(1000))
print(FiyatHesaplayici(PremiumIndirim()).hesapla(1000))
